import re;

def:pub excludeTags(content: str) -> str {
    return re.sub(r"<[^>]*>", "", content);
}

def:pub camelCase(data: str) -> str {
    def upper_match(`match: re.Match[str]) -> str {
        return `match.group().upper().strip();
    }
    return re.sub(r"\s\w", upper_match, data);
}

