import { useState, useEffect, useCallback } from 'react';

export const useToast = (duration = 1000) => {
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    if (showToast) setTimeout(() => setShowToast(false), duration);
  }, [showToast]);

  const displayToast = useCallback(() => {
    setShowToast(true);
  }, [])
  return { showToast, displayToast };
};

jac:
def:pub useToast(duration: int = 1000) -> dict[str, bool | Callable[[], None]] {
    has showToast: bool = False;

    def hideToast {
        showToast = False;
    }

    can with [showToast] entry {
        if showToast {
            setTimeout(hideToast, duration);
        }
    }

    def displayToast {
        showToast = True;
    }

    return {"showToast": showToast, "displayToast": displayToast};
}

