async def:pub getCurrentUser() -> dict[str, object] | None {
    try {
        session = await getSession();
        if not session {
            return None;
        }
        user = session.get("user");
        if not user {
            return None;
        }
        user_dict = user as dict[str, object];
        if not user_dict.get("email") {
            return None;
        }
        return user_dict;
    } except Exception {
        return None;
    }
}

