import from "next/head" { default as Head }
import from "react-redux" { useSelector }
import from "store" { RootState }
import from "store/slices/auth" { AuthState }
import from "api/customApi" { getMyRecipes }
import from "components" { Loading, CardList, Meta, EmptyPage, Heading, Pagination }
import from "store/services/types/queries" { SearchRecipeItem }
import from "next/router" { useRouter }

glob RESULTS_PER_PAGE = 12;

def select_auth(state: RootState) -> AuthState {
    return state.auth;
}

def:pub MyRecipes() -> JsxElement {
    has recipesToBeDisplayed: list[SearchRecipeItem] = [];
    has myRecipes: list[SearchRecipeItem] = [];
    has isLoading: bool = True;
    has currentPage: int = 1;

    auth_state = useSelector(select_auth);
    authUser = auth_state.authUser;
    authLoading = auth_state.isLoading;
    router = useRouter();

    async can with [authLoading, authUser] entry {
        if not authLoading and not authUser {
            router.push("/");
        }
    }

    async can with [authUser] entry {
        if not authUser {
            skip;
        } else {
            data = await getMyRecipes(authUser);
            myRecipes = data;
            recipesToBeDisplayed = data[0:RESULTS_PER_PAGE];
            isLoading = False;
        }
    }

    can with [currentPage] entry {
        start = (currentPage - 1) * RESULTS_PER_PAGE;
        end = currentPage * RESULTS_PER_PAGE;
        recipesToBeDisplayed = myRecipes[start:end];
        window.scrollTo(0, 0);
    }

    def handle_page_change(page: int) { currentPage = page; }

    if isLoading {
        return <Loading message="Loading my recipes" showBackground={False} />;
    }

    <>
        <Head>
            <title>My Recipes - TwoSpoon</title>
            <Meta data={{"title": "My Recipes - TwoSpoon"}} />
        </Head>
        {if len(myRecipes) == 0 {
            <EmptyPage>
                <Heading as="h2">Nothing saved</Heading>
                <p>Save recipes!</p>
            </EmptyPage>
        } else {
            <>
                <CardList results={recipesToBeDisplayed} />
                <Pagination
                    limit={RESULTS_PER_PAGE}
                    onClick={handle_page_change}
                    currentPage={currentPage}
                    totalResults={len(myRecipes)}
                />
            </>
        }}
    </>
}

