import json;
import re;

type CacheKey = str | int;

type Resource = dict[str, object];

type CacheKeyFn = Callable[[Resource], CacheKey];

type CacheFilter = Callable[[Resource], bool];

obj Cache {
    def get(key: CacheKey) -> object | None;
    def set(key: CacheKey, value: object) -> None;
    def delete(key: CacheKey) -> None;
    def clear() -> None;
}

glob SLASHES_PATTERN = r"(?:^/)|(?:/$)";

def _strip_slashes(value: str | None) -> str | None {
    if value is None {
        return None;
    }
    return re.sub(SLASHES_PATTERN, "", value);
}

def defaultCacheKeyGenerator(config: Resource) -> CacheKey {
    url = config.get("url");
    method = config.get("method");
    baseURL = config.get("baseURL");
    headers = config.get("headers");
    data = config.get("data");
    params = config.get("params");
    _baseURL = _strip_slashes(baseURL as str | None);
    _url = _strip_slashes(url as str | None);
    _method = method;
    if _method is not None {
        _method = (_method as str).lower();
    }
    payload = {
        "url": _url,
        "method": _method,
        "baseURL": _baseURL,
        "headers": headers,
        "data": data,
        "params": params,
    };
    return json.dumps(payload, sort_keys=True);
}

glob createCacheKey = None;

def wrapCache(provider: Cache) -> Cache {
    return provider;
}

