                        // @ts-ignore
                        onClick={successSound}
                        onMouseEnter={() => popSound()}
                        onMouseLeave={() => stopPopSound()}
                    >
                        Sign In
                    </button>
                </RegisterModal>

            )}
        </>
    )
}

export default Menu

