import from "@/utils/cn" { cn }

glob buttonVariantsConfig: dict[str, object] = {
    "base": [
        "inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium outline-none transition-all",
        "dark:aria-invalid:ring-destructive/40",
        "focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
        "aria-invalid:ring-destructive/20 aria-invalid:border-destructive",
        "disabled:pointer-events-none disabled:opacity-50",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0",
        "[&_svg:not([class*='size-'])]:size-4"
    ],
    "variants": {
        "variant": {
            "default": "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
            "destructive": "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
            "outline": "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
            "secondary": "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
            "ghost": "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
            "link": "text-primary underline-offset-4 hover:underline"
        },
        "size": {
            "default": "h-9 px-4 py-2 has-[>svg]:px-3",
            "sm": "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
            "lg": "h-10 rounded-md px-6 has-[>svg]:px-4",
            "icon": "size-9"
        }
    },
    "defaultVariants": {
        "variant": "default",
        "size": "default"
    }
};

def:pub buttonVariants(variant: str | None = None, size: str | None = None, className: str | None = None) -> str {
    defaults = buttonVariantsConfig["defaultVariants"] as dict[str, str];
    resolved_variant = variant if variant is not None else defaults["variant"];
    resolved_size = size if size is not None else defaults["size"];
    base_list = buttonVariantsConfig["base"] as list[str];
    variant_map = (buttonVariantsConfig["variants"] as dict[str, dict[str, str]])["variant"];
    size_map = (buttonVariantsConfig["variants"] as dict[str, dict[str, str]])["size"];
    return cn(*base_list, variant_map[resolved_variant], size_map[resolved_size], className) as str;
}

def:pub Button(props: dict[str, object]) -> JsxElement {
    className_val = props.get("className") as str | None;
    variant_val = props.get("variant") as str | None;
    size_val = props.get("size") as str | None;
    type_val = props.get("type", "button") as str;
    rest: dict[str, object] = {k: v for (k, v) in props.items() if k not in ["className", "variant", "size", "type"]};

    <button
        {**rest}
        data-slot="button"
        type={type_val}
        className={buttonVariants(variant=variant_val, size=size_val, className=className_val)}
    />
}

