import { twMerge } from 'tailwind-merge'

export const cn = (...inputs: ClassValue[]) => twMerge(clsx(inputs))

jac:
def:pub cn(*inputs: object) -> str {
    parts: list[str] = [];
    for item in inputs {
        if item and isinstance(item, str) {
            parts.append(item);
        }
    }
    return " ".join(parts);
}

