import from ..article.ArticlePreview { ArticlePreview }
import from ..common.Loading { Loading }
import from ..common.Pagination { Pagination }
import from ...api.article { getArticles }

def:pub Feed(query: str, url: str, limit: int) -> JsxElement {
    has articles: list[dict[str, object]] = [];
    has articlesCount: int = 0;
    has loading: bool = True;
    has page: int = 1;

    can with [query] entry {
        page = 1;
    }

    async can with [limit, query, page] entry {
        loading = True;
        try {
            result = await getArticles(
                f"{query}limit={limit}&offset={10 * (page - 1)}"
            );
            articles = result["articles"] as list[dict[str, object]];
            articlesCount = result["articlesCount"] as int;
            loading = False;
        } except Exception {
            loading = False;
        }
    }

    if loading {
        return <div className="article-preview">
            <Loading height={30} />
        </div>;
    }

    if articlesCount == 0 {
        return <div className="article-preview">No articles are here... yet.</div>;
    }

    return <>
        {[<ArticlePreview key={article["slug"] as str} article={article} /> for article in articles]}
        <Pagination articlesCount={articlesCount} url={url} />
    </>;
}

