import from "axios" { default as axios }

obj FetchWrapProps {
    has method: str;
    has url: str;
    has body: dict[str, object] | None = None;
    has signal: object | None = None;
}

async def fetchWrap(props: FetchWrapProps) -> object {
    method = props.method;
    url = props.url;
    body = props.body;
    signal = props.signal;
    jwtToken = localStorage.getItem("jwtToken");
    config = {
        "baseURL": "https://api.realworld.io/api",
        "headers": {
            "Authorization": f"Token {jwtToken}" if jwtToken else "",
        },
        "signal": signal,
    };
    try {
        if method == "get" {
            response = await axios.get(url, config);
        } elif method == "post" {
            response = await axios.post(url, body, config);
        } elif method == "put" {
            response = await axios.put(url, body, config);
        } elif method == "delete" {
            response = await axios.delete(url, config);
        } else {
            return {};
        }
        return response.data;
    } except Exception as e {
        raise e;
    }
}

async def GET(url: str, signal: object | None = None) -> object {
    return await fetchWrap(FetchWrapProps(method="get", url=url, signal=signal));
}

async def POST(url: str, body: dict[str, object] | None = None) -> object {
    return await fetchWrap(FetchWrapProps(method="post", url=url, body=body));
}

async def PUT(url: str, body: dict[str, object] | None = None) -> object {
    return await fetchWrap(FetchWrapProps(method="put", url=url, body=body));
}

async def DELETE(url: str) -> object {
    return await fetchWrap(FetchWrapProps(method="delete", url=url));
}

