import from "react" { useEffect }
import from "twilio-video" { Participant, RemoteParticipant, Room }

import from "./useToast" { useToast }

def bind_participant_events(
    active_room: Room,
    show_toast: Callable[[str, str], None],
    set_participants: Callable[[Callable[[list[Participant]], list[Participant]]], None],
) -> Callable[[], None] {
    def participant_connected(participant: RemoteParticipant) {
        set_participants(lambda (prev: list[Participant]) -> list[Participant] {
            return prev + [participant];
        });
    }
    def participant_disconnected(participant: RemoteParticipant) {
        show_toast("info", f"Participant {participant.identity} has disconnected from room");
        set_participants(lambda (prev: list[Participant]) -> list[Participant] {
            return [p for p in prev if p != participant];
        });
    }
    active_room.on("participantConnected", participant_connected);
    active_room.on("participantDisconnected", participant_disconnected);
    return lambda {
        active_room.off("participantConnected", participant_connected);
        active_room.off("participantDisconnected", participant_disconnected);
    };
}

def:pub useParticipants() -> dict[str, list[Participant]] {
    has participants: list[Participant] = [];

    toast_data = useToast();
    show_toast = toast_data["showToast"] as Callable[[str, str], None];

    room: Room | None = None;
    remote_participants: list[Participant] = [];
    local_participant: Participant | None = None;
    if room {
        remote_participants = list(room.participants.values());
        local_participant = room.localParticipant;
    }

    useEffect(lambda {
        if local_participant {
            participants = remote_participants + [local_participant];
        } else {
            participants = remote_participants;
        }
    }, [remote_participants, local_participant]);

    useEffect(lambda {
        if room {
            return bind_participant_events(
                room,
                show_toast,
                lambda (updater: Callable[[list[Participant]], list[Participant]]) {
                    participants = updater(participants);
                },
            );
        }
    }, [room]);

    return {"participants": participants};
}

