def:pub useClassNames() -> Callable[..., str] {
    def classify(*args: object) -> str {
        first_arg = args[0] if len(args) > 0 else "";
        second_arg = args[1] if len(args) > 1 else None;
        has_multiple_args = len(args) > 1;
        first = first_arg if has_multiple_args else "";
        second = second_arg if has_multiple_args else first_arg;
        if isinstance(second, dict) {
            keys = [k for k in second if second[k]];
            return (str(first) + " " + " ".join([str(k) for k in keys])).strip();
        }
        return str(first);
    }
    return classify;
}

