    audio_track: AudioTrackType = ctx["audioTrack"] as AudioTrackType;
    get_local_audio_track = ctx["getLocalAudioTrack"] as Callable[[], Awaitable[LocalAudioTrack]];
    room: Room | None = ctx["room"] as Room | None;
