import from "react" { useEffect }

import from "@/types" { IVideoTrack }

def setup_video_track(track: IVideoTrack, video_element: HTMLVideoElement, priority: str | None) {
    video_element.muted = True;
    if track.setPriority and priority {
        track.setPriority(priority);
    }
    track.attach(video_element);
}

def cleanup_video_track(track: IVideoTrack, video_element: HTMLVideoElement, priority: str | None) {
    track.detach(video_element);
    if track.setPriority and priority {
        track.setPriority(None);
    }
}

def run_video_effect(
    track: IVideoTrack,
    video_ref: Ref[HTMLVideoElement],
    priority: str | None,
) -> Callable[[], None] {
    video_element = video_ref.current;
    if video_element {
        setup_video_track(track, video_element, priority);
    }
    return lambda {
        video_element = video_ref.current;
        if video_element {
            cleanup_video_track(track, video_element, priority);
        }
    };
}

