    track: IVideoTrack,
    isLocal: bool | None = None,
    priority: str | None = None,
) -> JsxElement {
    has videoRef: Ref[HTMLVideoElement] = Ref();

    useEffect(lambda {
        return run_video_effect(track, videoRef, priority);
    }, [track, priority]);

    return <video ref={videoRef} />;
