import from .FacetValueState { isValidFacetValue }
import from .ServerSideConfig { IServerSideConfig }

def extractFieldName(fieldName: str) -> str {
    if fieldName.endswith("*") {
        return fieldName[:-1];
    }
    return fieldName;
}

def:pub isArrayFieldName(fieldName: str) -> bool {
