obj SearchResult {
    has key: str = "";
    has name: str = "";
    has keywordsFieldName: str = "";
    has keywords: list[str] = [];
    has coordinates: list[float] = [];
    has otherFields: list[str] = [];
    has highlightedWords: list[str] = [];
    has _config: IServerSideConfig = IServerSideConfig();

    def init(rawResult: dict[str, object], config: IServerSideConfig) {
        self._config = config;
        self.key = rawResult[config.CognitiveSearchKeyField] as str;
        coords = self.extractCoordinates(rawResult);
        self.coordinates = coords if coords is not None else [];
        self.highlightedWords = self.extractHighlightedWords(rawResult);
        parts: list[str] = [];
        for fieldName in config.CognitiveSearchNameField.split(",") {
            parts = parts + [rawResult[fieldName] as str];
        }
        self.name = ",".join(parts);
        otherFieldNames = [f for f in config.CognitiveSearchOtherFields.split(",") if f];
        for fieldName in otherFieldNames {
            fieldValue = rawResult[fieldName];
            if not fieldValue {
                continue;
            }
            if isinstance(fieldValue, list) {
                self.keywordsFieldName = extractFieldName(fieldName);
                deduped: list[str] = [];
                for val in fieldValue {
                    sval = val as str;
                    if isValidFacetValue(sval) and sval not in deduped {
                        deduped = deduped + [sval];
                    }
                }
                self.keywords = deduped;
                continue;
            }
            self.otherFields = self.otherFields + [str(fieldValue)];
        }
    }

    def extractCoordinates(rawResult: dict[str, object]) -> list[float] | None {
        coordinatesValue = rawResult[self._config.CognitiveSearchGeoLocationField];
        if coordinatesValue and isinstance(coordinatesValue, list) {
            return coordinatesValue as list[float];
        }
        if coordinatesValue and isinstance(coordinatesValue, dict) {
            coordDict = coordinatesValue as dict[str, object];
            for fieldName in coordDict {
                fieldVal = coordDict[fieldName];
                if fieldVal and isinstance(fieldVal, list) {
                    return fieldVal as list[float];
                }
            }
        }
        return None;
    }

    def extractHighlightedWords(rawResult: dict[str, object]) -> list[str] {
        result: list[str] = [];
        searchHighlights = rawResult["@search.highlights"];
        if not searchHighlights {
            return result;
        }
        highlightsDict = searchHighlights as dict[str, object];
        for fieldName in highlightsDict {
            highlightsArray = highlightsDict[fieldName] as list[str];
            for highlightString in highlightsArray {
                pos = 0;
                while pos < len(highlightString) {
                    start = highlightString.find("<em>", pos);
                    if start == -1 {
                        break;
                    }
                    end = highlightString.find("</em>", start + 4);
                    if end == -1 {
                        break;
                    }
                    result = result + [highlightString[start + 4:end]];
                    pos = end + 5;
                }
            }
        }
        return result;
    }
}

