import from "twilio-video" { AudioTrack, VideoTrack }

type TwilioTrack = AudioTrack | VideoTrack;

def bind_media_stream_events(
    active_track: TwilioTrack,
    set_media_stream_track: Callable[[object | None], None],
) -> Callable[[], None] {
    def handle_started {
        set_media_stream_track(active_track.mediaStreamTrack);
    }
    active_track.on("started", handle_started);
    return lambda {
        active_track.off("started", handle_started);
    };
}

def:pub useMediaStreamTrack(track: TwilioTrack | None = None) -> object | None {
    has mediaStreamTrack: object | None = track.mediaStreamTrack if track else None;

    useEffect(lambda {
        if track {
            current_track = track;
            mediaStreamTrack = current_track.mediaStreamTrack;
            return bind_media_stream_events(
                current_track,
                lambda (next_track: object | None) { mediaStreamTrack = next_track; },
            );
        }
        mediaStreamTrack = None;
    }, [track]);

    return mediaStreamTrack;
}

