import from "react" { useEffect }

def element_contains(container: object, child: object) -> bool {
    contains_fn = (container as dict)["contains"];
    return contains_fn.call(None, child) as bool;
}

def _handle_outside_click(
    ref: Ref[HTMLElement],
    ev: MouseEvent,
    callback: Callable[[], None],
) {
    current = ref.current;
    target = ev.target;
    if current and target and not element_contains(current, target) {
        callback();
    }
}

def:pub useOutsideClick(ref: Ref[HTMLElement], callback: Callable[[], None]) {
    useEffect(lambda {
        def handleOutsideClick(ev: MouseEvent) {
            _handle_outside_click(ref, ev, callback);
        }
        document.addEventListener("mousedown", handleOutsideClick);
        return lambda {
            document.removeEventListener("mousedown", handleOutsideClick);
        };
    }, [ref]);
}

