import from "react" { useEffect }
import from "twilio-video" { Participant }

def bind_reconnect_events(
    active_participant: Participant,
    set_is_reconnecting: Callable[[bool], None],
) -> Callable[[], None] {
    def handle_reconnecting {
        set_is_reconnecting(True);
    }
    def handle_reconnected {
        set_is_reconnecting(False);
    }
    handle_reconnected();
    active_participant.on("reconnecting", handle_reconnecting);
    active_participant.on("reconnected", handle_reconnected);
    return lambda {
        active_participant.off("reconnecting", handle_reconnecting);
        active_participant.off("reconnected", handle_reconnected);
    };
}

def:pub useParticipantIsReconnecting(participant: Participant) -> bool {
    has isReconnecting: bool = False;

    useEffect(lambda {
        return bind_reconnect_events(
            participant,
            lambda (next_value: bool) { isReconnecting = next_value; },
        );
    }, [participant]);

    return isReconnecting;
}
